//! Unicode normalization (UAX #15): NFC, NFD, NFKC and NFKD over the tables in
//! `norm_tables.rs` (generated by `scripts/gen-unicode.py`, D1760).
//!
//! Input and output are UTF-16 code units; lone surrogates pass through unchanged (they
//! have no decomposition and combining class 0). A quick check first decides most inputs
//! are already normalized, and then the caller keeps the original string.
use crate::PushOut;

use alloc::vec::Vec;

use super::norm_tables::{
    CCC_RUNS, CCC_VALUES, COMPOSE_EXCLUDED, DECOMP_ENTRIES, DECOMP_INDEX, DECOMP_TARGETS,
    INDEX_STEP, NFC_QC_MAYBE, NFC_QC_NO,
};
use super::tables::LEN_BITS;

/// A normalization form.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Form {
    Nfc,
    Nfd,
    Nfkc,
    Nfkd,
}

impl Form {
    fn compat(self) -> bool {
        matches!(self, Form::Nfkc | Form::Nfkd)
    }

    fn composes(self) -> bool {
        matches!(self, Form::Nfc | Form::Nfkc)
    }
}

// Hangul syllables (UAX #15 / Unicode 3.12), handled algorithmically.
const S_BASE: u32 = 0xAC00;
const L_BASE: u32 = 0x1100;
const V_BASE: u32 = 0x1161;
const T_BASE: u32 = 0x11A7;
const L_COUNT: u32 = 19;
const V_COUNT: u32 = 21;
const T_COUNT: u32 = 28;
const N_COUNT: u32 = V_COUNT * T_COUNT;
const S_COUNT: u32 = L_COUNT * N_COUNT;

/// The run in a packed range table (`start << LEN_BITS | len - 1`) containing `c`.
fn find_run(table: &[u32], c: u32) -> Option<usize> {
    let idx = table.partition_point(|&e| (e >> LEN_BITS) <= c);
    if idx == 0 {
        return None;
    }
    let e = table[idx - 1];
    (c <= (e >> LEN_BITS) + (e & ((1 << LEN_BITS) - 1))).then_some(idx - 1)
}

/// Canonical_Combining_Class.
pub fn ccc(c: u32) -> u8 {
    if c < 0x300 {
        return 0;
    }
    find_run(&CCC_RUNS, c).map_or(0, |i| CCC_VALUES[i])
}

#[inline(always)]
fn varint(bytes: &[u8], p: &mut usize) -> u32 {
    let b = bytes[*p];
    if b < 0x80 {
        *p += 1;
        return b as u32;
    }
    varint_long(bytes, p)
}

fn varint_long(bytes: &[u8], p: &mut usize) -> u32 {
    let mut v = 0;
    let mut shift = 0;
    loop {
        let b = bytes[*p];
        *p += 1;
        v |= ((b & 0x7F) as u32) << shift;
        if b < 0x80 {
            return v;
        }
        shift += 7;
    }
}

fn unzigzag(base: u32, z: u32) -> u32 {
    if z & 1 == 0 {
        base + (z >> 1)
    } else {
        base - ((z + 1) >> 1)
    }
}

/// Decodes the entries of index block `block` (the stream format is described in
/// `scripts/gen-unicode.py`, D2337) and calls `f(first, last, compat, mapping)` for each:
/// a run maps `first..=last` one-to-one onto consecutive code points from `mapping[0]`,
/// any other entry has `first == last`. `f` returns true to stop.
fn decode_block(block: usize, mut f: impl FnMut(u32, u32, bool, &[u32]) -> bool) {
    let (mut cp, e, t) = DECOMP_INDEX[block];
    let (mut pe, mut pt) = (e as usize, t as usize);
    // The previous entry's mapping, overwritten in place by each entry's: position i is
    // predicted by the previous entry's i-th code point while it had one.
    let mut map = [0u32; 18];
    map[0] = cp;
    let mut prev_len = 1;
    for k in 0..INDEX_STEP {
        if pe >= DECOMP_ENTRIES.len() {
            return;
        }
        let gap = varint(&DECOMP_ENTRIES, &mut pe);
        if k > 0 {
            cp += gap;
        }
        let header = varint(&DECOMP_ENTRIES, &mut pe);
        let (len, compat) = (header as usize >> 1, header & 1 != 0);
        let run = if len == 0 {
            varint(&DECOMP_ENTRIES, &mut pe)
        } else {
            0
        };
        let n = len.max(1);
        let mut last = 0;
        for (i, m) in map.iter_mut().enumerate().take(n) {
            let pred = if i < prev_len { *m } else { last };
            last = unzigzag(pred, varint(&DECOMP_TARGETS, &mut pt));
            *m = last;
        }
        if f(cp, cp + run, compat, &map[..n]) {
            return;
        }
        prev_len = n;
        cp += run;
    }
}

/// The single-level decomposition of `c` from the tables (Hangul excluded), appended to
/// `out`: whether it is a compatibility mapping, or `None` if `c` has none.
fn table_decomposition(c: u32, out: &mut Vec<u32>) -> Option<bool> {
    let i = DECOMP_INDEX.partition_point(|&(cp, _, _)| cp <= c);
    if i == 0 {
        return None;
    }
    let mut found = None;
    decode_block(i - 1, |first, last, compat, map| {
        if c < first {
            return true;
        }
        if c <= last {
            out.push_out(map[0] + (c - first));
            out.extend_from_slice(&map[1..]);
            found = Some(compat);
            return true;
        }
        false
    });
    found
}

/// Appends the full decomposition of `c` (canonical, or also compatibility) to `out`.
fn decompose_char(c: u32, compat: bool, out: &mut Vec<u32>) {
    if (S_BASE..S_BASE + S_COUNT).contains(&c) {
        let s = c - S_BASE;
        out.push_out(L_BASE + s / N_COUNT);
        out.push_out(V_BASE + (s % N_COUNT) / T_COUNT);
        let t = s % T_COUNT;
        if t != 0 {
            out.push_out(T_BASE + t);
        }
        return;
    }
    if c < 0xA0 {
        out.push_out(c);
        return;
    }
    let mut map = Vec::new();
    match table_decomposition(c, &mut map) {
        Some(is_compat) if compat || !is_compat => {
            for m in map {
                decompose_char(m, compat, out);
            }
        }
        _ => out.push_out(c),
    }
}

/// The primary composites, derived from the decompositions at the first composition
/// (D2338) and kept by the caller (the heap holds one per VM), so composing stays a binary
/// search.
#[derive(Default)]
pub struct Compositions {
    /// `first << 42 | second << 21 | composite`, sorted (so by the pair).
    pairs: Vec<u64>,
}

impl Compositions {
    fn ensure(&mut self) {
        if !self.pairs.is_empty() {
            return;
        }
        let mut pairs = Vec::new();
        for block in 0..DECOMP_INDEX.len() {
            decode_block(block, |cp, _, compat, map| {
                if !compat
                    && map.len() == 2
                    && ccc(cp) == 0
                    && ccc(map[0]) == 0
                    && COMPOSE_EXCLUDED.binary_search(&cp).is_err()
                {
                    pairs.push_out((map[0] as u64) << 42 | (map[1] as u64) << 21 | cp as u64);
                }
                false
            });
        }
        crate::sort::sort_by(&mut pairs, |x, y| x < y);
        self.pairs = pairs;
    }

    /// The primary composite of `a` and `b`, if any.
    fn pair(&mut self, a: u32, b: u32) -> Option<u32> {
        // Hangul LV and LVT.
        if (L_BASE..L_BASE + L_COUNT).contains(&a) && (V_BASE..V_BASE + V_COUNT).contains(&b) {
            return Some(S_BASE + ((a - L_BASE) * V_COUNT + (b - V_BASE)) * T_COUNT);
        }
        if (S_BASE..S_BASE + S_COUNT).contains(&a)
            && (a - S_BASE).is_multiple_of(T_COUNT)
            && (T_BASE + 1..T_BASE + T_COUNT).contains(&b)
        {
            return Some(a + (b - T_BASE));
        }
        // No primary composite has a second code point below U+0300.
        if b < 0x300 {
            return None;
        }
        self.ensure();
        let key = (a as u64) << 21 | b as u64;
        let i = self.pairs.partition_point(|&p| p >> 21 < key);
        let p = *self.pairs.get(i)?;
        (p >> 21 == key).then_some((p & 0x1F_FFFF) as u32)
    }
}

fn in_table(table: &[u32], c: u32) -> bool {
    find_run(table, c).is_some()
}

/// Whether the quick-check property of `form` is Yes for `c`. Only NFC's is a table
/// (localeCompare's hot path); the others follow from the decompositions (D2335).
fn quick_yes(c: u32, form: Form) -> bool {
    let nfc = || !in_table(&NFC_QC_NO, c) && !in_table(&NFC_QC_MAYBE, c);
    match form {
        Form::Nfc => nfc(),
        Form::Nfd | Form::Nfkd => {
            if (S_BASE..S_BASE + S_COUNT).contains(&c) {
                return false;
            }
            let mut map = Vec::new();
            match table_decomposition(c, &mut map) {
                Some(compat) => compat && form == Form::Nfd,
                None => true,
            }
        }
        Form::Nfkc => {
            if !nfc() {
                return false;
            }
            let (mut full, mut canonical) = (Vec::new(), Vec::new());
            decompose_char(c, true, &mut full);
            decompose_char(c, false, &mut canonical);
            full == canonical
        }
    }
}

/// Code points of UTF-16 units (lone surrogates as themselves).
fn code_points(units: &[u16]) -> Vec<u32> {
    char::decode_utf16(units.iter().copied())
        .map(|r| match r {
            Ok(ch) => ch as u32,
            Err(e) => e.unpaired_surrogate() as u32,
        })
        .collect()
}

/// The quick check (UAX #15 section 9): true only when `units` is certainly normalized in
/// `form` (YES), so it can be returned as is.
pub fn is_normalized_quick(units: &[u16], form: Form) -> bool {
    // Text below U+0300 has no combining marks; below U+00A0 nothing decomposes or
    // composes either (NFC of Latin-1 is itself).
    let fast_limit = if form == Form::Nfc { 0x300 } else { 0xA0 };
    if units.iter().all(|&u| u < fast_limit) {
        return true;
    }
    let mut last = 0u8;
    for r in char::decode_utf16(units.iter().copied()) {
        let c = match r {
            Ok(ch) => ch as u32,
            Err(_) => {
                last = 0;
                continue;
            }
        };
        if c < fast_limit as u32 {
            last = 0;
            continue;
        }
        let k = ccc(c);
        if k != 0 && last > k {
            return false;
        }
        if !quick_yes(c, form) {
            return false;
        }
        last = k;
    }
    true
}

/// Normalizes `units` to `form`. `comp` is the caller's cache of primary composites.
pub fn normalize(units: &[u16], form: Form, comp: &mut Compositions) -> Vec<u16> {
    let cps = code_points(units);
    // Decompose.
    let mut d = crate::buf::vec_with_capacity(cps.len());
    for &c in &cps {
        decompose_char(c, form.compat(), &mut d);
    }
    // Canonical ordering: a stable sort of each run of non-starters by class.
    let mut i = 0;
    while i < d.len() {
        if ccc(d[i]) == 0 {
            i += 1;
            continue;
        }
        let start = i;
        while i < d.len() && ccc(d[i]) != 0 {
            i += 1;
        }
        // Insertion sort (runs are short), stable.
        for j in start + 1..i {
            let mut k = j;
            while k > start && ccc(d[k - 1]) > ccc(d[k]) {
                d.swap(k - 1, k);
                k -= 1;
            }
        }
    }
    let out_cps = if form.composes() {
        compose(&d, comp)
    } else {
        d
    };
    let mut out = crate::buf::vec_with_capacity(out_cps.len());
    for c in out_cps {
        match char::from_u32(c) {
            Some(ch) => {
                let mut buf = [0u16; 2];
                out.extend_from_slice(ch.encode_utf16(&mut buf));
            }
            // A lone surrogate.
            None => out.push_out(c as u16),
        }
    }
    out
}

/// The canonical composition algorithm over a canonically ordered decomposition.
fn compose(d: &[u32], comp: &mut Compositions) -> Vec<u32> {
    let mut out: Vec<u32> = crate::buf::vec_with_capacity(d.len());
    let mut starter: Option<usize> = None;
    let mut last_ccc: i32 = -1;
    for &c in d {
        let k = ccc(c) as i32;
        if let Some(s) = starter {
            // Not blocked: nothing between the starter and c, or the last class is lower.
            let blocked = last_ccc != -1 && (last_ccc >= k || last_ccc == 0);
            if !blocked && let Some(p) = comp.pair(out[s], c) {
                out[s] = p;
                continue;
            }
        }
        if k == 0 {
            starter = Some(out.len());
            last_ccc = -1;
        } else {
            last_ccc = k;
        }
        out.push_out(c);
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn n(s: &str, f: Form) -> alloc::string::String {
        let u: Vec<u16> = s.encode_utf16().collect();
        alloc::string::String::from_utf16(&normalize(&u, f, &mut Compositions::default())).unwrap()
    }

    #[test]
    fn basics() {
        assert_eq!(n("e\u{301}", Form::Nfc), "\u{e9}");
        assert_eq!(n("\u{e9}", Form::Nfd), "e\u{301}");
        assert_eq!(n("\u{fb01}", Form::Nfkc), "fi");
        assert_eq!(n("\u{fb01}", Form::Nfc), "\u{fb01}");
        assert_eq!(n("\u{ac00}", Form::Nfd), "\u{1100}\u{1161}");
        assert_eq!(n("\u{1100}\u{1161}\u{11a8}", Form::Nfc), "\u{ac01}");
        assert_eq!(n("a\u{323}\u{307}", Form::Nfc), "\u{1ea1}\u{307}");
        assert_eq!(n("a\u{307}\u{323}", Form::Nfc), "\u{1ea1}\u{307}");
        assert_eq!(n("\u{212b}", Form::Nfc), "\u{c5}");
        assert_eq!(ccc(0x301), 230);
    }

    /// The quick check never says YES for a code point that changes, in any form: the
    /// derived checks of NFD, NFKD and NFKC (D2335) included.
    #[test]
    fn quick_yes_is_safe_for_every_code_point() {
        let mut buf = [0u16; 2];
        let mut comp = Compositions::default();
        for c in (0..0x110000u32).filter(|c| !(0xD800..0xE000).contains(c)) {
            let u = char::from_u32(c).unwrap().encode_utf16(&mut buf);
            for f in [Form::Nfc, Form::Nfd, Form::Nfkc, Form::Nfkd] {
                if quick_yes(c, f) {
                    assert_eq!(normalize(u, f, &mut comp), u.to_vec(), "{c:x} {f:?}");
                }
            }
        }
    }

    /// UCD's NormalizationTest.txt (fetched by scripts/gen-unicode.py into vendor/ of the
    /// primary checkout): every line, every form, and the quick check never says YES for
    /// a string that changes.
    #[test]
    fn normalization_test_txt() {
        extern crate std;
        use std::string::{String, ToString};
        let common = std::process::Command::new("git")
            .args(["rev-parse", "--path-format=absolute", "--git-common-dir"])
            .current_dir(env!("CARGO_MANIFEST_DIR"))
            .output()
            .expect("git");
        let common = String::from_utf8(common.stdout).unwrap();
        let root = std::path::Path::new(common.trim())
            .parent()
            .unwrap()
            .to_path_buf();
        let path = root.join("vendor/unicode/17.0.0/NormalizationTest.txt");
        let text = std::fs::read_to_string(&path)
            .unwrap_or_else(|_| panic!("{} missing: run scripts/gen-unicode.py", path.display()));
        let parse = |f: &str| -> Vec<u16> {
            let mut out = Vec::new();
            for cp in f.split_whitespace() {
                let c = char::from_u32(u32::from_str_radix(cp, 16).unwrap()).unwrap();
                let mut b = [0u16; 2];
                out.extend_from_slice(c.encode_utf16(&mut b));
            }
            out
        };
        let mut comp = Compositions::default();
        let mut lines = 0;
        let mut listed = std::collections::BTreeSet::new();
        for line in text.lines() {
            let line = line.split('#').next().unwrap().trim();
            if line.is_empty() || line.starts_with('@') {
                continue;
            }
            let c: Vec<Vec<u16>> = line.split(';').take(5).map(parse).collect();
            let (c1, c2, c3, c4, c5) = (&c[0], &c[1], &c[2], &c[3], &c[4]);
            // NFC: c2 == toNFC(c1..c3), c4 == toNFC(c4..c5); NFD: c3 / c5; NFKC: c4; NFKD: c5.
            for (x, want) in [(c1, c2), (c2, c2), (c3, c2), (c4, c4), (c5, c4)] {
                assert_eq!(&normalize(x, Form::Nfc, &mut comp), want, "NFC {line}");
                if is_normalized_quick(x, Form::Nfc) {
                    assert_eq!(x, want, "NFC quick check {line}");
                }
            }
            for (x, want) in [(c1, c3), (c2, c3), (c3, c3), (c4, c5), (c5, c5)] {
                assert_eq!(&normalize(x, Form::Nfd, &mut comp), want, "NFD {line}");
                if is_normalized_quick(x, Form::Nfd) {
                    assert_eq!(x, want, "NFD quick check {line}");
                }
            }
            for x in [c1, c2, c3, c4, c5] {
                assert_eq!(&normalize(x, Form::Nfkc, &mut comp), c4, "NFKC {line}");
                assert_eq!(&normalize(x, Form::Nfkd, &mut comp), c5, "NFKD {line}");
                if is_normalized_quick(x, Form::Nfkc) {
                    assert_eq!(x, c4, "NFKC quick check {line}");
                }
                if is_normalized_quick(x, Form::Nfkd) {
                    assert_eq!(x, c5, "NFKD quick check {line}");
                }
            }
            let cps = code_points(c1);
            if cps.len() == 1 {
                listed.insert(cps[0]);
            }
            lines += 1;
        }
        assert!(lines > 19_000, "{lines} lines");
        // Part 1's rule: code points not listed there are invariant under every form.
        for c in (0..0x110000u32).filter(|c| !(0xD800..0xE000).contains(c)) {
            if listed.contains(&c) {
                continue;
            }
            let s: Vec<u16> = char::from_u32(c)
                .unwrap()
                .to_string()
                .encode_utf16()
                .collect();
            for f in [Form::Nfc, Form::Nfd, Form::Nfkc, Form::Nfkd] {
                assert_eq!(normalize(&s, f, &mut comp), s, "{c:x} {f:?}");
            }
        }
    }
}
